/* Lernfortschritt bleibt ausschließlich im Browser dieses Geräts. */
'use strict';
const KEY='plan-markt-lernzirkel-v1';
const blank=()=>({version:1,station:0,phase:0,answers:{},checked:{},tasks:{},notes:{},reviewed:{},done:[],price:5,marketMode:'market'});
let state=blank(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw?.version===1){state={...blank(),...raw};state.station=Number.isInteger(raw.station)&&raw.station>=0&&raw.station<5?raw.station:0;state.phase=[0,1,2].includes(raw.phase)?raw.phase:0;for(const key of ['answers','checked','tasks','notes','reviewed'])if(!state[key]||typeof state[key]!=='object'||Array.isArray(state[key]))state[key]={};state.done=Array.isArray(raw.done)?raw.done.filter(n=>Number.isInteger(n)&&n>=0&&n<5):[];}}catch{storageOK=false;}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let notebook=false,home=true;
const criteria=[['decisions','Koordination / Steuerung'],['prices','Preisbildung'],['property','Produktionsmittel'],['wages','Lohnbildung'],['contracts','Vertragsverhältnisse'],['thinkers','Vordenker'],['goals','Zielsetzung'],['state','Rolle des Staates'],['principle','Grundprinzip'],['incentive','Leistungsanreize'],['strengths','Mögliche Stärken'],['risks','Mögliche Probleme']];
const stations=[{title:'Streng nach Plan',short:'Planwirtschaft',sub:'Entscheidungen & Eigentum',headline:'Wer entscheidet, was produziert wird?',goal:'Erkläre, wie eine zentrale Planung Produktion und Verteilung steuert.',time:'ca. 10 Minuten',system:'plan',fields:['decisions','prices','property'],reading:`<h2>Eine Zentrale gibt die Richtung vor</h2><p>In einer <strong>Zentralverwaltungswirtschaft</strong>, auch Planwirtschaft genannt, bestimmt eine staatliche Planungsbehörde, welche Güter in welchen Mengen produziert werden sollen. Betriebe melden ihre Möglichkeiten und erhalten verbindliche Vorgaben. Auch Preise und Löhne werden weitgehend staatlich festgelegt.</p><div class="flow" aria-label="Die Planungsbehörde gibt Betrieben und Haushalten Vorgaben. Diese melden Informationen zurück."><div class="central"><strong>Zentrale Planungsbehörde</strong><small>legt Ziele, Mengen und Preise fest</small></div><span class="flow-label">Vorgaben nach unten · Informationen zurück zur Zentrale</span><div><strong>Betriebe</strong><small>melden Kapazitäten, erfüllen Pläne</small></div><div><strong>Haushalte</strong><small>arbeiten, kaufen und melden Bedarf</small></div></div><p>Produktionsmittel wie Fabriken oder Maschinen gehören überwiegend dem Staat oder Genossenschaften. Das ist etwas anderes als persönliches Eigentum, etwa an Kleidung oder Möbeln. Ziel der Planung kann sein, die Grundversorgung zu sichern und Ressourcen gezielt einzusetzen.</p><div class="model-note"><strong>Modell und Wirklichkeit:</strong> Die DDR war überwiegend zentral geplant. Es gab jedoch auch private Betriebe und unterschiedliche Eigentumsformen. Nicht jede einzelne Entscheidung wurde von einer einzigen Behörde getroffen.</div>`,questions:[{id:'p-who',q:'Eine Fabrik soll im nächsten Jahr 20.000 Fahrräder herstellen. Wer legt diese Vorgabe im Modell fest?',options:['Die Kunden durch ihre einzelnen Kaufentscheidungen','Die zentrale Planungsbehörde','Die Beschäftigten durch eine Abstimmung'],correct:1,why:'In der Planwirtschaft koordiniert die Planungsbehörde die Produktion über verbindliche Mengen- und Produktionsvorgaben.',hint:'Überlege, wer im Schaubild die Vorgaben erteilt.'},{id:'p-own',q:'Was bedeutet staatliches Eigentum an Produktionsmitteln?',options:['Auch jedes private Fahrrad gehört dem Staat.','Alle Menschen können beliebig über jede Fabrik verfügen.','Der Staat besitzt zum Beispiel Fabriken und Maschinen.'],correct:2,why:'Produktionsmittel dienen der Herstellung von Gütern. Staatliches Eigentum daran bedeutet weder, dass jeder darüber frei verfügen darf, noch dass persönliches Eigentum abgeschafft ist.',hint:'Unterscheide Dinge für die Produktion von Dingen für den persönlichen Gebrauch.'}]},
{title:'Plan trifft Wirklichkeit',short:'Plan im Alltag',sub:'Stärken & Schwierigkeiten',headline:'Kann ein Plan alle Wünsche kennen?',goal:'Unterscheide Ziele der Planung von Problemen bei ihrer Umsetzung.',time:'ca. 12 Minuten',system:'plan',fields:['incentive','strengths','risks'],reading:'',questions:[]},
{title:'Der Markt koordiniert',short:'Marktwirtschaft',sub:'Preise & Entscheidungen',headline:'Wie stimmen sich viele Einzelne ab?',goal:'Untersuche, wie Angebot, Nachfrage und Preise Entscheidungen verbinden.',time:'ca. 15 Minuten',system:'market',fields:['decisions','prices','property'],reading:'',questions:[]},
{title:'Wettbewerb und Grenzen',short:'Markt im Alltag',sub:'Stärken & Schwierigkeiten',headline:'Was kann der Markt, wo liegen Grenzen?',goal:'Erkläre Anreize und prüfe, wann private Vorteile nicht allen zugutekommen.',time:'ca. 12 Minuten',system:'market',fields:['incentive','strengths','risks'],reading:'',questions:[]},
{title:'Dein Systemvergleich',short:'Vergleichen',sub:'Wissen anwenden',headline:'Zwei Wege, dieselben Grundfragen',goal:'Wende dein Wissen an und begründe den Unterschied zwischen beiden Modellen.',time:'ca. 12 Minuten',system:null,fields:[],reading:'',questions:[]}];
const extensionFields=['wages','contracts','thinkers','goals','state','principle'];
const modelNotes={plan:{decisions:'Eine zentrale staatliche Planungsbehörde erteilt verbindliche Produktionsvorgaben.',prices:'Preise werden weitgehend staatlich festgelegt.',property:'Überwiegend staatliches oder genossenschaftliches Eigentum an Produktionsmitteln.',incentive:'Planerfüllung steht im Mittelpunkt. Prämien sind möglich, können aber Fehlanreize schaffen.',strengths:'Ressourcen gezielt für gemeinsame Aufgaben bündeln; Grundversorgung und Beschäftigung als politische Ziele.',risks:'Informationsprobleme, Fehlanreize, Mangel oder Überschüsse und geringere Anpassungsfähigkeit.'},market:{decisions:'Unternehmen und Haushalte entscheiden dezentral. Ihre Entscheidungen werden über Märkte koordiniert.',prices:'Preise bilden sich durch Angebot und Nachfrage und signalisieren Knappheit.',property:'Überwiegend Privateigentum an Produktionsmitteln.',incentive:'Gewinne, Verluste und Wettbewerb schaffen Anreize für wirtschaftliches Handeln und Innovation.',strengths:'Wahlfreiheit, flexible Anpassung an Nachfrage, Anreize für Qualität, Innovation und Effizienz.',risks:'Ungleiche Kaufkraft, Marktmacht, externe Effekte, unzureichende Bereitstellung öffentlicher Güter und Krisen.'}};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-status').textContent=storageOK?'Auf diesem Gerät gespeichert. Auf gemeinsam genutzten iPads nach dem Export zurücksetzen.':'Speichern ist in diesem Browser nicht möglich. Sichere deine Ergebnisse über die Vergleichstabelle.';}
function invalidate(i){if(state.done.includes(i)){state.done=state.done.filter(n=>n!==i);nav();}}
function announce(text){$('#announcement').textContent=text;}
function nav(){const count=new Set(state.done).size;$('#progress').value=count;$('#progress-text').textContent=`${count} von 5`;$('#station-nav').innerHTML=stations.map((s,i)=>`<button class="station-link ${state.done.includes(i)?'done':''}" data-station="${i}" ${!home&&!notebook&&state.station===i?'aria-current="step"':''}><span class="station-number" aria-hidden="true">${state.done.includes(i)?'✓':i+1}</span><span><strong>${s.short}</strong><small>${state.done.includes(i)?'Abgeschlossen':s.sub}</small></span><span class="sr-only">${state.done.includes(i)?'Abgeschlossen':''}</span></button>`).join('');}
function render(focus=false){document.body.classList.toggle('home-view',home);$('.sidebar').hidden=home;nav();if(home){renderHome();save();if(focus)focusContent();return;}if(notebook){renderNotebook();save();if(focus)focusContent();return;}const s=stations[state.station];$('#main').innerHTML=`<div class="station-meta"><span class="tag">Station ${state.station+1} von 5</span><span>${s.time}</span></div><h1>${s.headline}</h1><p class="intro">${s.goal}</p><nav class="steps" aria-label="Lernphasen">${['Verstehen','Anwenden','Festhalten'].map((x,i)=>`<button class="step" data-phase="${i}" ${state.phase===i?'aria-current="true"':''}>${i+1}. ${x}</button>`).join('')}</nav><section class="sheet">${state.phase===0?s.reading:state.phase===1?practice(s):notes(s)}</section><div class="page-actions">${state.phase>0?'<button class="secondary" data-back>Zurück</button>':''}${state.phase<2?`<button class="primary" data-next>${state.phase===0?'Aufgaben bearbeiten':'Ergebnisse festhalten'} <span aria-hidden="true">→</span></button>`:'<button class="primary" data-complete>Station abschließen</button>'}</div><div id="station-message" role="status"></div>`;if(state.station===2&&state.phase===1)updateMarket();if(focus){$('#main').focus();window.scrollTo({top:0,behavior:'instant'});}save();}
function practice(s){return `<h2>${state.station===4?'Prüfe deinen Vergleich':'Jetzt bist du dran'}</h2>${originalPractice(state.station)}${state.station===2?marketHTML():''}<h3>Prüfe und begründe dein Verständnis</h3>${s.questions.map(q=>questionHTML(q)).join('')}`;}
function questionHTML(q){const answer=state.answers[q.id];const checked=state.checked[q.id];const correct=answer===q.correct;return `<fieldset class="question" data-question="${q.id}"><legend>${q.q}</legend><div class="choices">${q.options.map((o,i)=>`<label class="choice"><input type="radio" name="${q.id}" value="${i}" ${answer===i?'checked':''}><span>${o}</span></label>`).join('')}</div><details><summary>Hinweis öffnen</summary><p>${q.hint}</p></details><button class="secondary" data-check="${q.id}">Antwort prüfen</button><div id="feedback-${q.id}" role="status">${checked?feedback(correct,q.why):''}</div></fieldset>`;}
function feedback(ok,why){return `<div class="feedback ${ok?'good':''}"><strong>${ok?'Richtig eingeordnet.':'Noch nicht ganz. Versuche es erneut.'}</strong>${ok?why:'Nutze den Hinweis und prüfe, welches Merkmal des Modells hier entscheidend ist.'}</div>`;}
function notes(s){if(state.station===4)return finalNotes();const label=s.system==='plan'?'Zentralverwaltungswirtschaft':'Freie Marktwirtschaft';return `<h2>${state.station===1||state.station===3?'2. Stärken und Probleme herausarbeiten':'Deine Vergleichstabelle wächst'}</h2><p>Halte die drei Merkmale der <strong>${label}</strong> in eigenen Worten fest. Deine Notizen erscheinen später neben denen des anderen Modells.</p>${s.fields.map(f=>`<div class="note-field"><label for="note-${f}">${criteria.find(c=>c[0]===f)[1]}</label>${f==='strengths'?'<p class="small">Nenne mindestens drei mögliche Stärken bzw. Ziele. Erkläre kurz, warum sie möglich, aber nicht garantiert sind.</p>':f==='risks'?'<p class="small">Arbeite mindestens drei Probleme heraus und begründe sie mit Informationen, Regeln oder Anreizen.</p>':''}<textarea id="note-${f}" data-note="${s.system}:${f}" maxlength="1000" rows="3">${esc(state.notes[s.system+':'+f])}</textarea>${solutionGate([s.system+':'+f],`<p>${modelNotes[s.system][f]}</p>`)}</div>`).join('')}<label class="selfcheck"><input type="checkbox" data-review="${state.station}" ${state.reviewed[state.station]?'checked':''}><span>Ich habe meine Notizen mit den Lösungsvorschlägen verglichen und bei Bedarf verbessert.</span></label><p class="small">Freie Antworten prüfst du selbst. Sie werden nicht automatisch bewertet.</p>`;}
function setStation(i){home=false;state.started=true;state.station=i;state.phase=0;notebook=false;history.replaceState(null,'',`#station-${i+1}`);render(true);}
function complete(){const s=stations[state.station];const outstanding=s.questions.filter(q=>!state.checked[q.id]||state.answers[q.id]!==q.correct);const missing=s.fields.some(f=>String(state.notes[s.system+':'+f]??'').trim().length<8);const originalMissing=originalsMissing(state.station);const extensionMissing=state.station===4&&extensionFields.some(f=>['plan','market'].some(sys=>String(state.notes[sys+':'+f]??'').trim().length<8));const transferMissing=state.station===4&&String(state.notes.transfer??'').trim().length<20;if(originalMissing||extensionMissing||outstanding.length||missing||transferMissing||!state.reviewed[state.station]){$('#station-message').innerHTML=`<p class="feedback">${originalMissing?'Vervollständige und prüfe die Zuordnungen in „Anwenden“. ':''}${extensionMissing?'Ergänze die zusätzlichen Merkmale für beide Modelle. ':''}${outstanding.length?'Bearbeite zuerst alle Aufgaben in „Anwenden“ richtig. ':''}${missing?'Ergänze zu jedem Merkmal eine kurze eigene Notiz. ':''}${transferMissing?'Begründe deinen Vergleich mit mindestens einem vollständigen Satz. ':''}${!state.reviewed[state.station]?'Bestätige anschließend deinen Selbstcheck.':''}</p>`;$('#station-message').scrollIntoView({block:'nearest'});return;}if(!state.done.includes(state.station))state.done.push(state.station);save();if(state.station<4)setStation(state.station+1);else{showNotebook();}announce('Station abgeschlossen.');}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.station!==undefined)setStation(Number(t.dataset.station));if(t.dataset.phase!==undefined){state.phase=Number(t.dataset.phase);render(true);}if(t.hasAttribute('data-next')){state.phase++;render(true);}if(t.hasAttribute('data-back')){state.phase--;render(true);}if(t.dataset.check){const q=stations.flatMap(s=>s.questions).find(q=>q.id===t.dataset.check);if(state.answers[q.id]===undefined){$('#feedback-'+q.id).innerHTML='<p class="feedback">Wähle zuerst eine Antwort aus.</p>';return;}state.checked[q.id]=true;$('#feedback-'+q.id).innerHTML=feedback(state.answers[q.id]===q.correct,q.why);save();}if(t.hasAttribute('data-complete'))complete();});
document.addEventListener('change',e=>{const t=e.target;if(t.type==='radio'){state.answers[t.name]=Number(t.value);delete state.checked[t.name];invalidate(stations.findIndex(s=>s.questions.some(q=>q.id===t.name)));$('#feedback-'+t.name).innerHTML='';save();}if(t.dataset.review!==undefined){state.reviewed[t.dataset.review]=t.checked;if(!t.checked)invalidate(Number(t.dataset.review));save();}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.note){state.notes[t.dataset.note]=t.value;invalidate(state.station);state.reviewed[state.station]=false;const checkbox=$('[data-review]');if(checkbox)checkbox.checked=false;refreshSolutionGates(t.dataset.note);save();}});
$('.brand').addEventListener('click',e=>{e.preventDefault();showHome();});
$('#home-button').addEventListener('click',showHome);
$('#notebook-button').addEventListener('click',showNotebook);
$('#close-dialog').addEventListener('click',()=>$('#info-dialog').close());
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#info-dialog').showModal();}
$('#glossary-button').addEventListener('click',()=>modal('Begriffe zum Nachschlagen','<dl><dt>Produktionsmittel</dt><dd>Zum Beispiel Maschinen, Werkzeuge und Fabriken, die zur Herstellung von Gütern dienen.</dd><dt>Koordination</dt><dd>Abstimmung wirtschaftlicher Entscheidungen: Was wird wie und für wen produziert?</dd><dt>Anreiz</dt><dd>Ein erwarteter Vorteil oder Nachteil, der Entscheidungen beeinflusst, zum Beispiel Gewinn oder eine Prämie.</dd><dt>Knappheit</dt><dd>Güter und Mittel stehen nicht unbegrenzt zur Verfügung. Es muss entschieden werden, wofür sie eingesetzt werden.</dd><dt>Nachfrage</dt><dd>Die Menge eines Gutes, die Käufer zu einem bestimmten Preis kaufen wollen und bezahlen können.</dd><dt>Marktgleichgewicht</dt><dd>Bei einem bestimmten Preis stimmen angebotene und nachgefragte Menge überein.</dd><dt>Externer Effekt</dt><dd>Eine Auswirkung auf unbeteiligte Dritte, die im Marktpreis nicht berücksichtigt wird.</dd><dt>Genossenschaft</dt><dd>Ein Zusammenschluss von Mitgliedern, die gemeinsam wirtschaften. Genossenschaftliches Eigentum ist nicht dasselbe wie Staatseigentum.</dd></dl>'));
$('#reset-button').addEventListener('click',()=>modal('Lernfortschritt zurücksetzen?','<p>Alle Antworten und Notizen dieser Lernseite werden auf diesem Gerät gelöscht. Lade deine Vergleichstabelle vorher herunter, wenn du sie behalten möchtest.</p><button class="primary" id="confirm-reset">Fortschritt endgültig löschen</button>'));
document.addEventListener('click',e=>{if(e.target.id==='confirm-reset'){state=blank();$('#info-dialog').close();showHome();announce('Lernfortschritt zurückgesetzt.');}});
function comparisonHTML(){return `<table class="comparison"><caption class="sr-only">Deine Notizen zum Vergleich von Zentralverwaltungswirtschaft und freier Marktwirtschaft</caption><thead><tr><th scope="col">Merkmal</th><th scope="col">Zentralverwaltungs&shy;wirtschaft</th><th scope="col">Freie Marktwirtschaft</th></tr></thead><tbody>${criteria.map(([f,label])=>`<tr><th scope="row">${label}</th>${['plan','market'].map(system=>`<td data-system="${system==='plan'?'Zentralverwaltungswirtschaft':'Freie Marktwirtschaft'}">${state.notes[system+':'+f]?`<p>${esc(state.notes[system+':'+f])}</p>`:`<span class="empty-note">Noch keine Notiz. Ergänze sie in Station ${extensionFields.includes(f)?5:system==='plan'?(stations[0].fields.includes(f)?1:2):(stations[2].fields.includes(f)?3:4)}.</span>`}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function renderNotebook(){const all=state.done.length===5;$('#main').innerHTML=`${all?'<div class="completion"><h2>Dein Lernzirkel ist abgeschlossen.</h2><p>Du hast beide Modelle untersucht und deine Ergebnisse festgehalten. Sichere jetzt deinen Vergleich.</p></div>':''}<h1>Meine Vergleichstabelle</h1><p class="intro">Deine eigenen Ergebnisse. ${state.done.length} von 5 Stationen abgeschlossen.</p><div class="notebook-actions"><button class="primary" id="download-notes">Tabelle herunterladen</button><button class="secondary" id="print-notes">Drucken / als PDF sichern</button><button class="secondary" id="return-learning">Weiterlernen</button></div><div class="sheet">${comparisonHTML()}${state.notes.transfer?`<h2 class="transfer-heading">Mein begründeter Vergleich</h2><p class="student-transfer">${esc(state.notes.transfer)}</p>`:''}<p class="notebook-meta small">Modellvergleich: Tatsächliche Wirtschaftsordnungen weichen von diesen Grundmodellen ab. Deine freien Antworten sind selbst geprüft, nicht automatisch bewertet.</p></div><details><summary>Wie kann ich meine Notizen verbessern?</summary><p>Öffne die passende Station und dort „Festhalten“. Du kannst deine Einträge jederzeit ändern. Vergleiche sie anschließend erneut mit den Lösungsvorschlägen und schließe die Station wieder ab.</p></details>`;$('#return-learning').onclick=resumeLearning;$('#print-notes').onclick=()=>window.print();$('#download-notes').onclick=downloadNotes;}
function downloadNotes(){const html=`<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mein Vergleich: Planwirtschaft und Marktwirtschaft</title><style>body{font:17px/1.6 system-ui,sans-serif;color:#222;max-width:1100px;margin:40px auto;padding:24px}h1{font-size:28px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #aaa;padding:12px;vertical-align:top;text-align:left;overflow-wrap:anywhere}thead{background:#f2f2f2}p{white-space:pre-wrap}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.empty-note{color:#555}@media print{body{margin:0}tr{break-inside:avoid}}</style><h1>Planwirtschaft und freie Marktwirtschaft</h1><p>Meine Ergebnisse aus dem Lernzirkel Plan &amp; Markt. ${state.done.length} von 5 Stationen abgeschlossen.</p>${comparisonHTML()}${state.notes.transfer?`<h2>Mein begründeter Vergleich</h2><p>${esc(state.notes.transfer)}</p>`:''}${exerciseExport()}<p>Die Tabelle vergleicht theoretische Grundmodelle. Die freien Antworten wurden selbst geprüft, nicht automatisch bewertet.</p></html>`;const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Mein-Vergleich-Plan-und-Markt.html';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);announce('Deine Vergleichstabelle wird als HTML-Datei gespeichert.');}
function marketHTML(){return `<div class="market-lab"><h3>Der Spargelmarkt</h3><p>Ein Kälteeinbruch hat die Ernte verringert. Untersuche die Mengen bei verschiedenen Preisen. Die Zahlen sind vereinfachte Modellwerte.</p><details><summary>Die Anbieter und Käufer kennenlernen</summary><table class="market-table"><caption>Angebot im Marktmodell</caption><thead><tr><th scope="col">Anbieter</th><th scope="col">Menge</th><th scope="col">ab Preis / kg</th></tr></thead><tbody><tr><td>Anton, eigene Ernte</td><td>100 kg</td><td>5 €</td></tr><tr><td>Antons Bruder</td><td>100 kg</td><td>6 €</td></tr><tr><td>Berta</td><td>100 kg</td><td>7 €</td></tr><tr><td>Claus</td><td>100 kg</td><td>8 €</td></tr></tbody></table><p>200 kg werden von Schnäppchenjägern bis höchstens 5 € nachgefragt, weitere 200 kg von Spargelliebhabern bis höchstens 7 €. Ein Restaurant fragt im untersuchten Preisbereich zusätzlich 100 kg nach.</p></details><div class="pill-tabs" aria-label="Wirtschaftsmodell"><button class="secondary" data-market-mode="market" aria-pressed="${state.marketMode==='market'}">Marktmodell</button><button class="secondary" data-market-mode="plan" aria-pressed="${state.marketMode==='plan'}">Planmodell</button></div><p id="market-explanation" class="small"></p><label for="market-price" id="price-label"><strong>Preis pro Kilogramm</strong></label><div class="market-controls"><button class="secondary" data-price-step="-1" aria-label="Preis um einen Euro senken">−</button><input id="market-price" type="range" min="5" max="9" step="1" value="${state.price}" aria-describedby="price-description"><output for="market-price" class="price-readout" id="price-output"></output><button class="secondary" data-price-step="1" aria-label="Preis um einen Euro erhöhen">+</button></div><p id="price-description" class="sr-only">Ändere den Preis zwischen 5 und 9 Euro pro Kilogramm. Die angebotene und nachgefragte Menge wird darunter angezeigt.</p><div class="market-metrics"><div class="metric"><span>Angebot</span><strong id="supply-value"></strong><div class="bar-track" aria-hidden="true"><div class="bar" id="supply-bar"></div></div></div><div class="metric"><span>Nachfrage</span><strong id="demand-value"></strong><div class="bar-track" aria-hidden="true"><div class="bar demand" id="demand-bar"></div></div></div></div><div class="market-result" role="status" aria-live="polite" id="market-result"></div><p class="small lab-caveat">Der Mengenvergleich allein erklärt noch keine Wirtschaftsordnung. Entscheidend ist, wer Preise und Produktionsmengen verändert.</p></div>`;}
function marketValues(price,mode){const supply=mode==='plan'?300:Math.min(400,(price-4)*100);const demand=price<=5?500:price<=7?300:100;return {supply,demand};}
function updateMarket(){if(!$('#market-price'))return;state.price=Math.max(5,Math.min(9,Number(state.price)||5));if(!['plan','market'].includes(state.marketMode))state.marketMode='market';const p=state.price,mode=state.marketMode,{supply,demand}=marketValues(p,mode);$('#market-price').value=p;$('#price-output').textContent=`${p} €`;$('#supply-value').textContent=`${supply} kg`;$('#demand-value').textContent=`${demand} kg`;$('#supply-bar').style.width=`${supply/5}%`;$('#demand-bar').style.width=`${demand/5}%`;$('#market-explanation').textContent=mode==='market'?'Beobachte: Bei höheren Preisen lohnt sich das Angebot für zusätzliche Anbieter. Käufer mit geringerer Zahlungsbereitschaft steigen aus.':'Die Planungsbehörde legt hier 300 kg Produktion fest und setzt den Preis. Wir nehmen an, dass die geplante Menge hergestellt wird. Preisänderungen ändern diesen Produktionsplan nicht automatisch.';$('#price-label').innerHTML=`<strong>${mode==='plan'?'Staatlich festgelegter Preis':'Untersuchter Marktpreis'} pro Kilogramm</strong>`;const result=supply===demand?'<strong>Angebot und Nachfrage stimmen überein.</strong> 300 kg können verkauft werden.':demand>supply?`<strong>Nachfrageüberschuss: ${demand-supply} kg.</strong> Nicht alle Kaufwünsche können erfüllt werden.`:`<strong>Angebotsüberschuss: ${supply-demand} kg.</strong> Ein Teil des Angebots findet zu diesem Preis keine Käufer.`;const action=mode==='market'?(supply===demand?'Im Modell liegt das Marktgleichgewicht bei 7 € pro kg.':demand>supply?'Der Nachfrageüberschuss kann zu steigenden Preisen führen.':'Der Angebotsüberschuss kann zu sinkenden Preisen führen.'):'Die Behörde müsste Preis, Produktionsplan oder Zuteilung anpassen. Ob und wie schnell das gelingt, hängt unter anderem von ihren Informationen ab.';$('#market-result').innerHTML=`<p>${result}</p><p>${action}</p>`;document.querySelectorAll('[data-market-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.marketMode===mode)));document.querySelector('[data-price-step="-1"]').disabled=p===5;document.querySelector('[data-price-step="1"]').disabled=p===9;}
document.addEventListener('input',e=>{if(e.target.id==='market-price'){state.price=Number(e.target.value);updateMarket();save();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.priceStep){state.price=Math.max(5,Math.min(9,Number(state.price)+Number(b.dataset.priceStep)));updateMarket();save();}if(b.dataset.marketMode){state.marketMode=b.dataset.marketMode;updateMarket();save();}});
function finalNotes(){return `${extendedComparisonFields()}<h2>Begründe deinen Vergleich</h2><p>Eine Region braucht mehr Fahrräder. Erkläre, wie die Entscheidung über eine höhere Produktion in den beiden Modellen zustande kommt. Nenne für jedes Modell eine mögliche Schwierigkeit.</p><label for="transfer"><strong>Meine Erklärung</strong></label><textarea id="transfer" data-note="transfer" rows="6" maxlength="3000">${esc(state.notes.transfer)}</textarea><details><summary>Schreibhilfe</summary><p>„In der Zentralverwaltungswirtschaft entscheidet … Dafür braucht die Behörde … Eine Schwierigkeit ist … In der freien Marktwirtschaft reagieren … Dabei kann es passieren, dass …“</p></details>${solutionGate(['transfer'],`<p>In der Zentralverwaltungswirtschaft muss die Planungsbehörde den höheren Bedarf erkennen und den Betrieben neue Produktionsvorgaben geben. Dazu benötigt sie Informationen über Bedarf und verfügbare Mittel. Diese können unvollständig oder verspätet sein.</p><p>In der freien Marktwirtschaft können höhere Nachfrage und steigende Preise Unternehmen dazu anregen, mehr Fahrräder anzubieten. Sie erwarten dadurch Gewinne. Eine Schwierigkeit ist, dass Menschen mit geringem Einkommen trotz ihres Bedarfs möglicherweise kein Fahrrad kaufen können.</p>`)}<label class="selfcheck"><input type="checkbox" data-review="4" ${state.reviewed[4]?'checked':''}><span>Ich habe meine zusätzlichen Tabellenfelder verglichen. Meine Erklärung nennt für beide Modelle den Entscheidungsträger, den Weg zur höheren Produktion und eine mögliche Schwierigkeit.</span></label><p class="small">Prüfe deine Erklärung selbst anhand des Lösungsvorschlags. Auch andere fachlich begründete Antworten sind möglich.</p>`;}
Object.assign(stations[1],{reading:`<h2>Zwischen Versorgungsziel und Informationsproblem</h2><p>Ein zentraler Plan kann Ressourcen gezielt bündeln, etwa für Wohnungsbau oder die Versorgung mit Grundnahrungsmitteln. Beschäftigung und eine gleichmäßigere Verteilung können politische Ziele sein. <strong>Ein Ziel ist aber noch kein garantiertes Ergebnis.</strong></p><p>Die Planung muss sehr viele Informationen verarbeiten: Was brauchen Haushalte? Welche Rohstoffe fehlen? Was können Betriebe leisten? Ändern sich Wünsche oder Liefermöglichkeiten, kann ein Plan schnell unpassend werden.</p><div class="fact-pair"><div><strong>Der Schraubenauftrag</strong><p>Ein Betrieb wird nach der Anzahl produzierter Schrauben bewertet. Er könnte viele kleine Schrauben herstellen, obwohl größere gebraucht werden.</p></div><div><strong>Was die Kennzahl übersieht</strong><p>Eine hohe Stückzahl sagt wenig darüber aus, ob die Schrauben brauchbar sind. Planerfüllung und tatsächlicher Bedarf können auseinanderfallen.</p></div></div><p>Auch in der DDR gab es Gewinne und Leistungsprämien. Das Problem waren nicht grundsätzlich fehlende Anreize, sondern auch <strong>Fehlanreize</strong>: Gute Kennzahlen konnten wichtiger werden als Qualität, Innovation oder Verbraucherwünsche.</p><div class="model-note"><strong>Historisches Beispiel:</strong> Lange Wartezeiten auf einen Trabant zeigen, dass staatliche Versorgungsvorgaben Mangel nicht automatisch verhinderten. Solche Folgen sind von den erklärten Zielen zu unterscheiden.</div>`,questions:[{id:'plan-target',q:'Welche Aussage unterscheidet Ziel und Ergebnis richtig?',options:['Ein zentraler Plan garantiert eine optimale Versorgung.','Grundversorgung kann ein Ziel sein; Informationsprobleme können die Umsetzung erschweren.','Wo geplant wird, kann es grundsätzlich keine Versorgung geben.'],correct:1,why:'Die gezielte Sicherung einer Grundversorgung ist ein mögliches politisches Ziel. Ob es erreicht wird, hängt unter anderem von Informationen, Ressourcen und Anreizen ab.',hint:'Suche die Aussage, die weder Erfolg noch Scheitern automatisch voraussetzt.'},{id:'plan-screw',q:'Warum kann eine reine Stückzahlvorgabe zu vielen kleinen Schrauben führen?',options:['Der Betrieb optimiert die belohnte Kennzahl, auch wenn sie den Bedarf schlecht abbildet.','Kleine Schrauben werden grundsätzlich häufiger gebraucht.','In einer Planwirtschaft können Menschen keine großen Schrauben herstellen.'],correct:0,why:'Die Kennzahl setzt einen Anreiz. Wird nur die Stückzahl bewertet, kann der Betrieb seine Vorgabe erfüllen, obwohl die Produktion nicht zum Bedarf passt.',hint:'Welche Leistung wird in diesem Beispiel belohnt: Brauchbarkeit oder Stückzahl?'},{id:'plan-reward',q:'Welche Formulierung ist fachlich angemessen?',options:['In der DDR gab es überhaupt keine Leistungsprämien.','Die DDR hatte dasselbe Anreizsystem wie eine freie Marktwirtschaft.','Auch in der DDR gab es Prämien; die Bindung an Planziele konnte Fehlanreize schaffen.'],correct:2,why:'Prämien und betriebliche Gewinne gab es. Entscheidend ist, an welche Ziele ein Anreiz geknüpft ist und welches Verhalten dadurch belohnt wird.',hint:'Das Vorhandensein eines Anreizes bedeutet noch nicht, dass er sinnvoll wirkt.'}]});
Object.assign(stations[2],{reading:`<h2>Viele Entscheidungen, verbunden durch Preise</h2><p>In der <strong>freien Marktwirtschaft</strong> entscheiden Unternehmen selbst, welche Güter sie anbieten und wie sie produzieren. Haushalte entscheiden, was sie kaufen. Produktionsmittel befinden sich überwiegend in Privateigentum.</p><p>Die Entscheidungen werden über <strong>Märkte</strong> aufeinander abgestimmt. Ein Preis informiert über Knappheit: Wird ein Gut stärker nachgefragt oder knapper angeboten, kann sein Preis steigen. Das kann zusätzliche Anbieter anziehen und manche Käufer vom Kauf abhalten.</p><div class="flow"><div><strong>Unternehmen</strong><small>bieten Güter an, erwarten Gewinne</small></div><div><strong>Haushalte</strong><small>fragen Güter nach, entscheiden über Käufe</small></div><div class="central"><strong>Markt und Preis</strong><small>stimmen Angebot und Nachfrage aufeinander ab</small></div></div><p>Wer ein Gut erhält, hängt von <strong>Zahlungsbereitschaft und Kaufkraft</strong> ab. Ein dringender Bedarf allein reicht nicht. Einkommen und Vermögen sind zudem kein eindeutiges Maß für die persönliche Leistung.</p><details><summary>Vordenker: Adam Smith</summary><p>Der schottische Ökonom Adam Smith beschrieb, wie Eigeninteresse unter geeigneten Bedingungen zum gesellschaftlichen Wohlstand beitragen kann. Daraus folgt keine Garantie, dass jeder Markt allen Menschen nützt.</p></details><div class="model-note"><strong>Modell und Wirklichkeit:</strong> Eine vollständig freie Marktwirtschaft ist ein theoretisches Modell. Auch die USA haben staatliche Regeln und Eingriffe.</div>`,questions:[{id:'market-balance',q:'Stelle im Marktmodell den Preis ein. Bei welchem Preis stimmen Angebot und Nachfrage überein?',options:['5 € pro kg bei 100 kg','7 € pro kg bei 300 kg','8 € pro kg bei 400 kg'],correct:1,why:'Bei 7 € bieten Anton, sein Bruder und Berta zusammen 300 kg an. Spargelliebhaber und Restaurant fragen zusammen 300 kg nach.',hint:'Probiere 5, 7 und 8 Euro aus und vergleiche jeweils beide Mengen.'},{id:'market-shortage',q:'Was ist bei 5 € im Marktmodell zu beobachten?',options:['500 kg Nachfrage treffen auf 100 kg Angebot: 400 kg Nachfrageüberschuss.','100 kg Nachfrage treffen auf 500 kg Angebot.','Alle Käufer bekommen ihre gewünschte Menge.'],correct:0,why:'Bei 5 € kaufen alle drei Käufergruppen: 200 + 200 + 100 = 500 kg. Nur Anton bietet 100 kg an. Es fehlen 400 kg.',hint:'Lies bei 5 Euro die beiden Mengen ab. Ziehe das Angebot von der Nachfrage ab.'},{id:'market-plan',q:'Wechsle zum Planmodell. Warum bleibt das Angebot dort bei einer Preisänderung zunächst bei 300 kg?',options:['Haushalte kaufen bei jedem Preis dieselbe Menge.','Private Anbieter bestimmen den staatlichen Plan.','In diesem Beispiel ist die Produktionsmenge vorgegeben; eine Preisänderung ändert den Plan nicht automatisch.'],correct:2,why:'Im vereinfachten Planmodell wird die Menge vorgegeben. Im Marktmodell passen Anbieter ihre Entscheidungen an den Preis an. Das ist der zentrale Unterschied der Koordination.',hint:'Achte darauf, wer in jedem Modell die Produktionsmenge bestimmt.'}]});
Object.assign(stations[3],{reading:`<h2>Wettbewerb setzt Anreize</h2><p>Wer gute Produkte zu attraktiven Preisen anbietet, kann Kunden gewinnen und Gewinne erzielen. Unternehmen, deren Produkte niemand kaufen möchte, riskieren Verluste. Das schafft Anreize für <strong>Qualität, Innovation und einen sparsamen Ressourceneinsatz</strong>. Haushalte haben Wahlmöglichkeiten, Unternehmen unternehmerische Freiheit.</p><p>Diese Anreize garantieren aber keine Ergebnisse, die für alle Menschen gleichermaßen gut sind. Große Unternehmen können Marktmacht erlangen. Kosten für unbeteiligte Dritte können unberücksichtigt bleiben. Und wer wenig Geld besitzt, kann sich auch dringend benötigte Güter möglicherweise nicht leisten.</p><div class="fact-pair"><div><strong>Effizienz</strong><p>Wie lassen sich vorhandene Mittel möglichst wirksam einsetzen? Wettbewerb kann dazu beitragen.</p></div><div><strong>Verteilung</strong><p>Wer erhält wie viel? Eine effiziente Produktion bedeutet nicht automatisch eine als gerecht empfundene Verteilung.</p></div></div><p>Reine öffentliche Güter, etwa der Schutz durch einen Deich, können über freiwillige Zahlungen unzureichend bereitgestellt werden. Auch Wirtschaftskrisen und Arbeitslosigkeit sind möglich.</p><div class="model-note"><strong>Direkter Vergleich:</strong> Die Planwirtschaft setzt auf staatliche Koordination und politische Ziele. Die freie Marktwirtschaft setzt auf dezentrale Entscheidungen und Preissignale. Beide müssen mit knappen Mitteln und unvollständigen Informationen umgehen.</div>`,questions:[{id:'market-incentive',q:'Zwei Bäckereien konkurrieren um Kunden. Welcher Anreiz ist typisch für das Marktmodell?',options:['Die zentrale Behörde schreibt jeder Bäckerei dieselbe Absatzmenge vor.','Bessere Qualität und günstigere Herstellung können mehr Kunden und Gewinne bringen.','Jede Bäckerei erhält unabhängig vom Absatz denselben Gewinn.'],correct:1,why:'Wettbewerb kann Unternehmen dazu anregen, ihre Angebote zu verbessern und wirtschaftlicher zu produzieren. Ein garantierter Erfolg folgt daraus nicht.',hint:'Überlege, wie ein Unternehmen Kunden gewinnt, die zwischen Angeboten wählen können.'},{id:'market-fair',q:'Eine Familie braucht dringend ein Fahrrad, kann es aber nicht bezahlen. Was zeigt das?',options:['Auf Märkten zählt neben dem Wunsch auch die Kaufkraft.','Marktpreise werden allein nach der Dringlichkeit des Bedarfs festgelegt.','Der Bedarf der Familie kann deshalb nicht echt sein.'],correct:0,why:'Marktnachfrage ist zahlungsfähige Nachfrage. Deshalb können dringende Bedürfnisse unerfüllt bleiben. Effizienz und Verteilungsgerechtigkeit sind unterschiedliche Fragen.',hint:'Bedarf und zahlungsfähige Nachfrage sind nicht dasselbe.'},{id:'market-limits',q:'Welcher Vergleich ist angemessen?',options:['Die Planwirtschaft ist immer gerecht; die Marktwirtschaft ist immer effizient.','In beiden Modellen sind alle Menschen automatisch gleich gut versorgt.','Beide Modelle haben mögliche Stärken und typische Probleme; gute Ergebnisse sind nicht garantiert.'],correct:2,why:'Die Systeme nutzen unterschiedliche Koordinationsmechanismen. Ihre Ziele, Anreize und möglichen Ergebnisse müssen getrennt beurteilt werden.',hint:'Achte auf pauschale Wörter wie „immer“ und „automatisch“.'}]});
Object.assign(stations[4],{reading:`<h2>Vergleiche den Mechanismus</h2><p>Beide Modelle beantworten dieselben Fragen: <strong>Was wird produziert? Wie wird produziert? Wer erhält die Güter?</strong> Der wichtigste Unterschied liegt darin, wie wirtschaftliche Entscheidungen koordiniert werden.</p><div class="fact-pair"><div><strong>Zentralverwaltungswirtschaft</strong><p>Zentrale Vorgaben steuern Produktion und Verteilung. Preise und Mengen werden weitgehend geplant. Staatliches oder genossenschaftliches Eigentum überwiegt.</p></div><div><strong>Freie Marktwirtschaft</strong><p>Unternehmen und Haushalte entscheiden dezentral. Angebot, Nachfrage und Preise koordinieren ihre Entscheidungen. Privateigentum überwiegt.</p></div></div><p>Prüfe bei Stärken und Problemen immer die Begründung: Welcher Anreiz oder welche Information führt zu welchem Verhalten? Vermeide Aussagen wie „immer gerecht“ oder „automatisch effizient“.</p><details><summary>Modell und historische Umsetzung auseinanderhalten</summary><p>Die DDR eignet sich als historisches Beispiel einer überwiegend zentral geplanten Wirtschaft. Die USA sind marktwirtschaftlich geprägt, haben aber ebenfalls staatliche Regeln und Eingriffe. Ein Land entspricht deshalb nicht einfach einem reinen Modell.</p><p>Marx und Engels waren wichtige Vordenker des Sozialismus; sie haben nicht die konkrete spätere DDR-Wirtschaftsordnung entworfen. Adam Smith war ein wichtiger Vordenker der klassischen Ökonomie.</p></details><div class="model-note"><strong>Dein Abschluss:</strong> Beantworte die Vergleichsfragen und erkläre anschließend an einem Beispiel, wie beide Modelle reagieren.</div>`,questions:[{id:'final-coordinate',q:'Welche Gegenüberstellung trifft die Koordination am besten?',options:['Zentrale verbindliche Vorgaben gegenüber dezentraler Abstimmung über Märkte.','Arbeit gegenüber Freizeit.','Moderne Maschinen gegenüber alten Maschinen.'],correct:0,why:'Entscheidend ist die Art der Abstimmung wirtschaftlicher Entscheidungen, nicht das Alter der Technik.',hint:'Frage: Wer trifft Entscheidungen und wie werden sie abgestimmt?'},{id:'final-ownership',q:'Welche Gegenüberstellung zum Eigentum ist richtig?',options:['Kein persönliches Eigentum gegenüber Eigentum aller Menschen an allen Betrieben.','Überwiegend staatliche/genossenschaftliche gegenüber überwiegend privaten Produktionsmitteln.','In beiden Modellen gehören alle Betriebe dem Staat.'],correct:1,why:'Die Unterscheidung betrifft insbesondere Produktionsmittel. Persönliches Eigentum und genossenschaftliches Eigentum müssen davon sauber unterschieden werden.',hint:'Denke an Fabriken und Maschinen, nicht an Kleidung oder Möbel.'},{id:'final-price',q:'Ein Gut wird knapper. Worin unterscheiden sich die Modelle?',options:['In der Planwirtschaft kann Knappheit nicht entstehen.','Im Marktmodell wird jeder Preis vom Staat festgelegt.','Im Marktmodell können Preise und Anbieter reagieren; im Planmodell muss die zuständige Stelle Vorgaben anpassen.'],correct:2,why:'Preissignale koordinieren dezentrale Entscheidungen. Bei verbindlichen Vorgaben hängt eine Anpassung von den Entscheidungen der zuständigen Planungsstellen ab.',hint:'Vergleiche deinen Versuch im Spargelmarkt mit dem vorgegebenen Produktionsplan.'},{id:'final-incentives',q:'Welche Aussage zu Anreizen ist richtig?',options:['Anreize gibt es ausschließlich in der freien Marktwirtschaft.','Beide Modelle können Anreize setzen, aber sie knüpfen an unterschiedliche Ziele und Regeln an.','Prämien verhindern grundsätzlich alle Fehlentscheidungen.'],correct:1,why:'Marktgewinne und Planprämien sind unterschiedliche Anreize. In beiden Fällen kommt es darauf an, welches Verhalten sie tatsächlich belohnen.',hint:'Erinnere dich an die Schraubenkennzahl und die konkurrierenden Bäckereien.'},{id:'final-country',q:'Wie solltest du DDR und USA in einem Vergleich verwenden?',options:['Als historische bzw. reale Beispiele, die nicht vollständig den reinen Modellen entsprechen.','Als Beweis, dass Wirtschaftsmodelle genau der Wirklichkeit entsprechen.','Als zwei Länder mit völlig identischen Wirtschaftsordnungen.'],correct:0,why:'Modelle vereinfachen. Die DDR war überwiegend zentral geplant; auch die marktwirtschaftlich geprägten USA haben staatliche Eingriffe.',hint:'Unterscheide das theoretische Grundmodell von seiner tatsächlichen Umsetzung.'}]});
$('#sources-button').addEventListener('click',()=>modal('Quellen & Hinweise',`<p>Der Lernzirkel vergleicht theoretische Grundmodelle auf dem Niveau der 11. Klasse. Er wurde aus einer Stationenarbeit zu Zentralverwaltungswirtschaft und Marktwirtschaft fachlich überarbeitet. Die Texte sind neu formuliert; die Spargelaufgabe nutzt vereinfachte Modellzahlen.</p><h3>Zum Vertiefen und Nachprüfen</h3><ul><li><a href="https://www.bpb.de/kurz-knapp/lexika/lexikon-der-wirtschaft/20292/planwirtschaft/" target="_blank" rel="noopener noreferrer">bpb: Planwirtschaft</a></li><li><a href="https://www.bpb.de/themen/deutsche-teilung/ddr-kompakt/521636/wirtschaftliche-reformprogramme-seit-1962-63/" target="_blank" rel="noopener noreferrer">bpb: Wirtschaftsreformen, Gewinne und Prämien in der DDR</a></li><li><a href="https://www.bpb.de/themen/deutschlandarchiv/513381/alles-nach-plan/" target="_blank" rel="noopener noreferrer">bpb: Planung und ihre Umsetzung in der DDR</a></li><li><a href="https://www.gla.ac.uk/explore/adamsmith300/lifeworkandlegacy/life/" target="_blank" rel="noopener noreferrer">Universität Glasgow: Adam Smith</a></li><li><a href="https://www.federalreserve.gov/faqs/money_12855.htm" target="_blank" rel="noopener noreferrer">Federal Reserve: Geld- und Fiskalpolitik in den USA</a></li><li><a href="https://www.bpb.de/lernen/angebote/grafstat/umweltbewusstsein/134847/info-05-05-oeffentliche-gueter/" target="_blank" rel="noopener noreferrer">bpb: Öffentliche Güter</a></li></ul><h3>Deine Antworten</h3><p>Diese Lernseite speichert Antworten und Notizen ausschließlich im Browser auf diesem Gerät. Es gibt keine Übermittlung deiner Antworten an Lehrkräfte und keine automatische Bewertung freier Texte. Bei einem Gerätewechsel werden deine Antworten nicht übernommen. Sichere sie über die Vergleichstabelle. Auf gemeinsam genutzten Geräten setzt du deinen Fortschritt danach zurück.</p><p class="small">Inhaltlich geprüft: September 2026. Externe Quellen öffnen in einem neuen Tab.</p>`));
Object.assign(modelNotes.plan,{wages:'Löhne und Lohnstrukturen werden weitgehend staatlich festgelegt.',contracts:'Wirtschaftliche Verträge und Entscheidungen sind an verbindliche Pläne gebunden; die Vertragsfreiheit ist stark eingeschränkt.',thinkers:'Karl Marx und Friedrich Engels als Vordenker des Sozialismus. Sie entwarfen nicht die konkrete spätere DDR-Wirtschaftsordnung.',goals:'Erfüllung politisch gesetzter Planziele, etwa Versorgung und Beschäftigung. Diese Ziele werden nicht automatisch erreicht.',state:'Der Staat plant, koordiniert, kontrolliert und trifft zentrale wirtschaftliche Entscheidungen.',principle:'Zentrale Lenkung; historisch häufig mit sozialistischen Vorstellungen und gesellschaftlichem Eigentum verbunden.'});
Object.assign(modelNotes.market,{wages:'Löhne entstehen im Modell durch Angebot und Nachfrage auf Arbeitsmärkten und durch Vereinbarungen.',contracts:'Unternehmen und Haushalte schließen grundsätzlich freiwillig Verträge innerhalb eines Rechtsrahmens.',thinkers:'Adam Smith als wichtiger Vordenker der klassischen Ökonomie und des wirtschaftlichen Liberalismus; kein alleiniger Erfinder der Marktwirtschaft.',goals:'Unternehmen streben nach Gewinn, Haushalte nach der Befriedigung ihrer Bedürfnisse innerhalb ihres Budgets.',state:'Im liberalen Grundmodell sichert der Staat vor allem den Rechtsrahmen, Eigentum, Verträge und äußere Sicherheit.',principle:'Dezentrale Entscheidungen, Eigeninteresse, Wettbewerb und individuelle wirtschaftliche Freiheit.'});
function extendedComparisonFields(){return `<section class="original-task"><p class="eyebrow">Station 5 aus deinem Arbeitsblatt</p><h2>Teste dein Wissen: Ergänze den Vergleich</h2><p>Sechs Merkmale hast du bereits in den Stationen gesammelt. Ergänze jetzt die weiteren Felder deiner ursprünglichen Tabelle <strong>zuerst möglichst ohne nachzuschauen</strong>. Öffne die Lösungsvorschläge erst zur Selbstkontrolle.</p><p class="small">„Begründer“ heißt hier genauer „Vordenker“. DDR und USA werden als Beispiele eingeordnet, nicht mit den reinen Modellen gleichgesetzt.</p>${extensionFields.map(f=>`<fieldset class="comparison-field"><legend>${criteria.find(c=>c[0]===f)[1]}</legend><div class="comparison-inputs">${['plan','market'].map(sys=>`<div><label for="extended-${sys}-${f}">${sys==='plan'?'Zentralverwaltungswirtschaft':'Freie Marktwirtschaft'}</label><textarea id="extended-${sys}-${f}" data-note="${sys}:${f}" rows="3" maxlength="1000">${esc(state.notes[sys+':'+f])}</textarea></div>`).join('')}</div>${solutionGate(['plan:'+f,'market:'+f],`<p><strong>Plan:</strong> ${modelNotes.plan[f]}</p><p><strong>Markt:</strong> ${modelNotes.market[f]}</p>`,'Lösungsvorschläge vergleichen')}</fieldset>`).join('')}</section>`;}
stations.forEach((s,i)=>s.time=['ca. 20 Minuten','ca. 15 Minuten','ca. 20 Minuten','ca. 15 Minuten','ca. 20 Minuten'][i]);
stations[0].reading+=`<details><summary>Für deinen späteren Vergleich: Löhne, Verträge und Staat</summary><p>Im Modell werden Löhne weitgehend staatlich festgesetzt. Verträge zwischen Betrieben sind an verbindliche Pläne gebunden; ihre wirtschaftliche Vertragsfreiheit ist stark eingeschränkt. Der Staat ist zentrale Planungs-, Entscheidungs- und Kontrollinstanz.</p><p>Die zentrale Lenkung war historisch häufig mit sozialistischen Vorstellungen verbunden. Marx und Engels waren wichtige Vordenker des Sozialismus, entwarfen aber nicht die konkrete spätere DDR-Wirtschaftsordnung.</p></details>`;
stations[0].questions.push({id:'plan-low',q:'2a. Festgesetzte Preise: Es werden 300 kg eines Gutes angeboten. Bei einem niedrigen festgelegten Preis wollen Haushalte 500 kg kaufen. Welche Folge ist möglich?',options:['200 kg bleiben ohne Käufer.','Es fehlen 200 kg; Wartezeiten oder Zuteilung können entstehen.','Der Bedarf verschwindet automatisch.'],correct:1,why:'500 kg Nachfrage minus 300 kg Angebot ergeben 200 kg Nachfrageüberschuss. Ein niedriger Preis allein vergrößert die vorgegebene Produktionsmenge nicht.',hint:'Vergleiche die Kaufwünsche mit der verfügbaren Menge.'},{id:'plan-high',q:'2b. Bei einem höheren festgelegten Preis werden von den 300 kg nur 100 kg nachgefragt. Was folgt?',options:['200 kg Angebotsüberschuss; Preis oder Produktionsplan müssten geprüft werden.','200 kg Nachfrageüberschuss.','Die Haushalte kaufen automatisch den Rest.'],correct:0,why:'Es werden 200 kg mehr angeboten als nachgefragt. Die Behörde kann auf diese Information mit veränderten Vorgaben reagieren. Hier bleibt das Angebot zunächst planbedingt fest; wir übertragen nicht ungeprüft eine Markt-Angebotskurve auf die Planwirtschaft.',hint:'Ziehe die nachgefragte von der angebotenen Menge ab.'});
stations[2].reading+=`<details><summary>Für deinen späteren Vergleich: Löhne, Verträge und Staat</summary><p>Im Modell bilden sich Löhne durch Angebot und Nachfrage am Arbeitsmarkt sowie Vereinbarungen zwischen den Beteiligten. Grundsätzlich gilt Vertragsfreiheit. Das setzt einen Rechtsrahmen voraus.</p><p>Im liberalen Grundmodell sichert der Staat insbesondere Eigentum, Verträge und äußere Sicherheit. „Freie Marktwirtschaft“ bedeutet deshalb nicht, dass es überhaupt keinen Staat gibt. Individuelle wirtschaftliche Freiheit ist ein Grundprinzip. Unternehmen verfolgen Gewinnziele, Haushalte ihre Bedürfnisse im Rahmen ihres Budgets.</p></details>`;
stations[2].questions.push({id:'market-adjust',q:'2b. Aus der Spargelaufgabe: Warum ändern sich bei steigenden Preisen Angebot und Nachfrage?',options:['Alle Käufer kaufen immer mehr.','Die Planungsbehörde befiehlt allen Anbietern dieselbe Menge.','Anbieter mit höheren Kosten können einsteigen; Käufer mit niedrigerer Zahlungsbereitschaft steigen aus.'],correct:2,why:'Bei höheren Preisen wird das Angebot auch für Anbieter mit höheren Kosten lohnend. Gleichzeitig kaufen einige Nachfrager weniger oder gar nicht. So wirkt der Preismechanismus.',hint:'Vergleiche die Preisgrenzen der Anbieter und Käufer im Marktmodell.'},{id:'market-claus',q:'2d. Warum bietet Claus beim Gleichgewichtspreis von 7 € keinen Spargel an?',options:['Seine Kosten von 8 € pro kg liegen über dem erzielbaren Preis.','Ein staatlicher Plan verbietet ihm den Verkauf.','Es gibt bei 7 € grundsätzlich keine Nachfrage.'],correct:0,why:'Claus würde je verkauftem Kilogramm 1 € unter seinen hier angenommenen Stückkosten erlösen. Im Modell lohnt sich sein Angebot deshalb erst ab 8 €.',hint:'Vergleiche Claus’ Kosten mit dem Preis von 7 Euro.'});
stations[2].questions.find(q=>q.id==='market-balance').q='2c. Aus der Spargelaufgabe: Bei welchem Preis und welcher Menge wird der Markt geräumt?';
stations[2].questions.find(q=>q.id==='market-shortage').q='2a. Aus der Spargelaufgabe: Warum ist ein Preis von 5 € nicht markträumend?';
stations[3].reading+=`<details><summary>Öffentliche Güter: zwei Merkmale</summary><p>Bei einem reinen öffentlichen Gut können Menschen kaum von der Nutzung ausgeschlossen werden. Zugleich verringert die Nutzung durch eine Person die Nutzungsmöglichkeiten anderer nicht. Ein Beispiel ist der Schutz durch einen Deich innerhalb des geschützten Gebiets.</p><p>U-Bahnfahrten sind dagegen kein reines öffentliches Gut: Zugangskontrollen sind möglich und Plätze können knapp sein. Das Schwarzfahrer-Rollenspiel des Arbeitsblatts zeigt ein Finanzierungsproblem, aber keinen sauberen Gegensatz zwischen Plan- und Marktwirtschaft.</p></details>`;
stations[4].reading+=`<details><summary>Optional zu zweit: Vergleiche beide Perspektiven</summary><p>Übernehmt nacheinander zwei Rollen: erst eine Planungsbehörde und einen Betrieb, dann ein Unternehmen und einen Haushalt. In der Region werden mehr Fahrräder gebraucht. Besprecht für beide Modelle: Wer entscheidet über zusätzliche Produktion? Welche Informationen werden gebraucht? Was passiert, wenn Wünsche und Produktion nicht zusammenpassen?</p><p>Haltet danach allein euren begründeten Vergleich fest. Die Partneraufgabe ist freiwillig; alle Pflichtaufgaben lassen sich allein bearbeiten.</p></details>`;
// Previously completed stations must also satisfy newly digitized tasks.
state.done=state.done.filter(i=>!originalsMissing(i)&&stations[i].questions.every(q=>state.checked[q.id]&&state.answers[q.id]===q.correct)&&(i!==4||extensionFields.every(f=>['plan','market'].every(sys=>String(state.notes[sys+':'+f]??'').trim().length>=8))));

if(document.modelContext?.registerTool){const lifecycle=new AbortController();const registrations=[{name:'read_learning_progress',title:'Lernfortschritt lesen',description:'Liest abgeschlossene Stationen und den aktuellen Lernschritt, ohne Antworten oder Notizen zu verändern.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Ein leeres Objekt wird erwartet.');return {station:state.station+1,phase:['Verstehen','Anwenden','Festhalten'][state.phase],completedStations:state.done.map(i=>i+1)};}},{name:'open_learning_station',title:'Lernstation öffnen',description:'Öffnet eine Lernstation in der Phase Verstehen. Beantwortet keine Aufgaben und schließt keine Station ab.',inputSchema:{type:'object',properties:{station:{type:'integer',minimum:1,maximum:5}},required:['station'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.station)||input.station<1||input.station>5||Object.keys(input).some(k=>k!=='station'))throw new Error('Eine Station von 1 bis 5 wird erwartet.');setStation(input.station-1);return {station:state.station+1,title:stations[state.station].title};}}];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
applyReadingContent();
readPageRoute();
render();
